function validate([arrivalTime, delayedTime]) {
  if (!Number.isInteger(arrivalTime) || arrivalTime < 1 || arrivalTime > 23) return 'arrivalTime is a whole number from 1 to 23.';
  if (!Number.isInteger(delayedTime) || delayedTime < 1 || delayedTime > 24) return 'delayedTime is a whole number from 1 to 24.';
  return null;
}

