function findDelayedArrivalTime(arrivalTime, delayedTime) {
  // Move the clock forward one hour at a time.
  let hour = arrivalTime;
  for (let step = 0; step < delayedTime; step++) {
    hour++;
    if (hour === 24) hour = 0;
  }
  return hour;
}

