function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const pick = (low, high) => {
    const roll = rand();
    if (size === 'small' && roll < 0.15) return low;
    if (size === 'small' && roll < 0.3) return high;
    return int(low, high);
  };
  return [pick(1, 23), pick(1, 24)];
}
